    private final Supplier<ImperiumCharacter> creator;
    private final List<Location> spawnLocations;
    private ImperiumCharacter mask;

    public static void initializeAll() {
        for (NPCs value : values()) {
            val quests = Fantasy.questService().findAllQuests().stream()
                    .filter(quest -> quest.getStorageNpc() == value || quest.getPassQuestNpc() == value)
                    .map(Quest::getId).collect(Collectors.toList());

            value.getSpawnLocations().forEach(location -> {
                val character = value.getCreator().get();
                character.addQuests(new ArrayList<>(quests));
                character.updateData(value);
                character.initializeSmartNpc(location);

                CharacterProvider.getInstance().registerCharacter(character);
            });

            value.mask = value.getCreator().get();
            value.getMask().updateData(value);
        }
    }

